export default function SubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const trimmed = email.trim();
  const invalid = submitted && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
      setSubmitted(true);
      return;
    }
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${trimmed}`,
      variant: 'success',
    });
    setEmail('');
    setSubmitted(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxWidth: '360px' }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        autoComplete="email"
        placeholder="you@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        helperText="Присылаем письма не чаще раза в неделю"
